/* deliveryMapper.selectAssignDeliveryList : */ SELECT od.OD_JOB_NO ,od.MBL_NO ,od.HBL_NO ,od.BOUND ,od.BOUND_TYPE ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM330' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM330' )A ) AS POD_ECM330 FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO
WHERE od.ENT_CODE = #{entCode} AND od.BL_TYPE_MH = 'H' AND (ISNULL(ad.DELIVERY_STATUS,'') < 'ECM340' or ISNULL(ad.DELIVERY_STATUS,'') ='ECM350')
AND od.MBL_NO = #{srchMblNo}
AND od.OD_JOB_NO IN(#{item.odJobNo})

mapper.update:
/* deliveryMapper.assignDelivery : Delivery 배송사 지정 */
	UPDATE TB_ECM_OD
	SET DELIVERY_CODE = #{deliveryCode}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE ENT_CODE = #{entCode} 
	AND OD_JOB_NO = #{odJobNo}

/* deliveryMapper.assignDeliveryExcel : Delivery 배송사 지정 엑셀 업로드 */
	UPDATE TB_ECM_OD SET 
	DELIVERY_CODE = #{deliveryCode}
	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE ENT_CODE = #{entCode} AND MBL_NO = LTRIM(RTRIM(#{mblNo})) AND HBL_NO = LTRIM(RTRIM(#{hblNo}))

		/* deliveryMapper.updateDelivery : Delivery 배송지 정보 변경 */
			UPDATE TB_ECM_OD 
			SET UPDATE_USER_ID = #{updateUserId}
			, UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			
				, CONSIGNEE_NAME_LOC = #{consigneeName}
			
			
				, CONSIGNEE_ZIPCODE = #{consigneeZipcode}
						
			
				
				, CONSIGNEE_ADDRESS_LOC = #{deliveryAddressChanged}
			
			
				, DELIVERY_PAYMENT_TYPE = #{deliveryPaymentType}
			
			, DELIVERY_NAME_CHANGED = DELIVERY_NAME
			
			
			




			  
			  
				
					, CONSIGNEE_TEL_ENC = dbo.Cryptography(#{odJobNo}, #{consigneeTel}, 0)
					, CONSIGNEE_HP_ENC = dbo.Cryptography(#{odJobNo}, #{consigneeTel}, 0)
				
			  
			  
				
					, CONSIGNEE_TEL = #{consigneeTel} 
					, CONSIGNEE_HP = #{consigneeTel}
				
			  
			  
			WHERE ENT_CODE = #{entCode} AND OD_JOB_NO = #{odJobNo}

/* deliveryMapper.cancelDelivery : Delivery 배송사 취소,보류 */
UPDATE TB_ECM_OD_ADDITIONAL SET DELIVERY_STATUS = 'ECM350'
WHERE OD_JOB_NO = #{item.odJobNo};
UPDATE TB_ECM_OD_ADDITIONAL SET DELIVERY_STATUS = 'ECM350'
WHERE OD_JOB_NO IN ( SELECT od.OD_JOB_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO
WHERE od.ENT_CODE = #{entCode} AND od.BL_TYPE_MH = 'H'
)

mapper.select:
/* deliveryMapper.selectOdJobNos : Delivery 검색으로 선택하여 배송사 취소,보류시 검색건 데이터 조회 */ SELECT od.OD_JOB_NO AS odJobNo ,od.HBL_No AS blNo ,od.DELIVERY_CODE AS deliveryCode ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM350' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM350' ) A ) AS ECM350_POD_JOB_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO
LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO
WHERE od.ENT_CODE = #{entCode} AND od.BL_TYPE_MH = 'H'

mapper.update:
		/* deliveryMapper.updateDeliveryPod350 : Delivery 배송사 취소,보류(ECM350)      사용안함  */

			UPDATE TB_ECM_POD SET
			POD_DATE = DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
			, POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE()), 108)
			, UPDATE_USER_ID = #{updateUserId}
			, UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			WHERE POD_STATUS = 'ECM350' AND OD_JOB_NO = #{odJobNo}
						
			IF @@ROWCOUNT = 0
			
			BEGIN
			INSERT INTO TB_ECM_POD(
				 POD_JOB_NO
				,ENT_CODE
				,OD_JOB_NO
				,POD_STATUS
				,POD_NAME
				,POD_DATE
				,POD_TIME
				,BL_NO
				,DELIVERY_CODE
				,REGISTER_USER_ID
				,REGISTER_DATE_TIME
				,UPDATE_USER_ID
				,UPDATE_DATE_TIME
			)VALUES(
				 #{podJobNo}
				,#{entCode}
				,#{odJobNo}
				,'ECM350'
				,'배송사지정'
				,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
				,CONVERT(VARCHAR(5), DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE()), 108)
				,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
				,#{deliveryCode}
				,#{registerUserId}
				,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
				,#{registerUserId}
				,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
			);			
			END

mapper.select:
		/* deliveryMapper.selectDeliveryInterface : 배송사 Interface 정보 조회 */
			SELECT  
				TOP 1
				*
			FROM TB_SMS_DELIVERY_COMP_INFO
			WHERE ENT_CODE = #{entCode}
			AND CUSTOMER_CODE = #{srchCustomerCode}
			 
				AND BOUND = 'AIR'
				AND BOUND = 'SEA'
			
			
			
			
			AND LOGISTICS_CODE = #{srchLogisticsCode}

/* deliveryMapper.selectSendDeliveryList : Delivery 각 배송사에 해당하는 데이터 조회 */ SELECT od.HBL_NO , od.OD_JOB_NO , od.HSN , od.CUST_CODE_LV1 AS AGENT_CODE , od.DEST_PORT , ad.LAST_POD_STATUS , od.VESSEL_FLIGHT , CASE ISNULL(od.PO_NO,'') WHEN '' THEN od.HBL_NO ELSE od.PO_NO END PO_NO , od.CONSIGNEE_NAME_LOC , od.CONSIGNEE_NAME , od.CONSIGNEE_ZIPCODE , od.CONSIGNEE_ADDRESS , od.CONSIGNEE_ADDRESS_A , od.CONSIGNEE_ADDRESS_B , od.PIECES , od.CBM , od.GWT , od.DELIVERY_NOTE , od.AMOUNT_CUR , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '1'),'|','') as commodityItem1 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '2'),'|','') as commodityItem2 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '3'),'|','') as commodityItem3 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '4'),'|','') as commodityItem4 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '5'),'|','') as commodityItem5 , od.COMMODITY_ITEM AS commodityItemLocConvert , od.PIECES_REAL , od.SHIPPER_NAME AS shipperNameConvert , CASE WHEN ISNULL(od.CONSIGNEE_NAME_LOC,'') = '' THEN ISNULL(od.CONSIGNEE_NAME,'') ELSE ISNULL(od.CONSIGNEE_NAME_LOC,'') END AS consigneeNameLocConvert , od.SHIPPER_ZIPCODE AS shipperZipcodeConvert , od.SHIPPER_ADDRESS + ISNULL(od.SHIPPER_ADDRESS_A,'') + ISNULL(od.SHIPPER_ADDRESS_B,'') + ISNULL(od.SHIPPER_ADDRESS_C,'') + ISNULL(od.SHIPPER_ADDRESS_D,'') AS shipperAddressLocConvert , od.SHIPPER_TEL AS shipperTelConvert , od.SHIPPER_HP AS shipperMobileConvert , od.CONSIGNEE_ZIPCODE AS consigneeZipcodeLocConvert , LEFT(REPLACE(ISNULL(od.CONSIGNEE_ADDRESS_LOC, od.CONSIGNEE_ADDRESS + ISNULL(od.CONSIGNEE_ADDRESS_A,'') + ISNULL(od.CONSIGNEE_ADDRESS_B,'') + ISNULL(od.CONSIGNEE_ADDRESS_C,'') + ISNULL(od.CONSIGNEE_ADDRESS_D,'')),'|',' '), 200) AS consigneeAddressLocConvert , od.TR_CODE , od.DELIVERY_CODE , od.MBL_NO , od.DELIVERY_PAYMENT_TYPE , od.BOUND , od.BOUND_TYPE , #{registerUserId} AS registerUserId , #{registerUserName} AS registerUserName , #{gmtTime} AS gmtTime ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' ) A ) AS ECM340_POD_JOB_NO , mti.DELIVERY_NO
, CASE WHEN ISNULL(od.CONSIGNEE_HP_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) END AS CONSIGNEE_HP , dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) AS consigneeHpConvert , dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS consigneeTelConvert
, CASE WHEN ISNULL(od.CONSIGNEE_HP,'') = '' THEN ISNULL(od.CONSIGNEE_TEL,'') ELSE ISNULL(od.CONSIGNEE_HP,'') END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL,'') = '' THEN ISNULL(od.CONSIGNEE_HP,'') ELSE ISNULL(od.CONSIGNEE_TEL,'') END AS CONSIGNEE_HP , od.CONSIGNEE_HP AS consigneeHpConvert , od.CONSIGNEE_TEL AS consigneeTelConvert
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI mti ON od.OD_JOB_NO = mti.OD_JOB_NO WHERE od.CONSOL_YN = 'Y' AND ISNULL(od.HBL_NO,'') != '' AND (ISNULL(ad.DELIVERY_STATUS,'') < 'ECM340' OR ad.DELIVERY_STATUS = 'ECM350')
AND ( (ISNULL(mti.OD_JOB_NO,'') != '' AND ISNULL(mti.RETURN_DELIVERY_STATUS,'') != 'ECM425') OR (ISNULL(mti.OD_JOB_NO,'') = '' AND ISNULL(ad.DELIVERY_STATUS,'') != 'ECM425') )
AND od.DELIVERY_CODE = #{deliveryCode}
AND ISNULL(od.DELIVERY_CODE, '') != '' AND ISNULL(ad.DELIVERY_STATUS, '') < 'ECM340'
AND ad.DELIVERY_STATUS = #{srchStatus}
AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP' AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'
AND od.CUST_CODE_LV1 = #{srchEcmCustomerCode}
AND od.MBL_NO IN
#{item.mblNo}
AND od.OD_JOB_NO IN
#{item.odJobNo}
ORDER BY od.CUST_CODE_LV1

mapper.update:
/* deliveryMapper.updateDeliveryStatus : Delivery 각 배송사 배송요청 후 상태값 업데이트(ECM340)       사용안함 */
	UPDATE TB_ECM_OD_ADDITIONAL SET  
	  DELIVERY_STATUS = 'ECM340' 
	, LAST_POD_STATUS = CASE WHEN ISNULL(LAST_POD_STATUS, '') < 'ECM340' THEN 'ECM340' ELSE LAST_POD_STATUS END
	
	WHERE OD_JOB_NO = #{OD_JOB_NO};
	
	UPDATE TB_ECM_POD SET
	POD_DATE = DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
	, POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE()), 108)
	, UPDATE_USER_ID = #{registerUserId}
	, UPDATE_DATE_TIME = CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	WHERE POD_STATUS = 'ECM340' AND OD_JOB_NO = #{OD_JOB_NO}
				
	IF @@ROWCOUNT = 0
	
	BEGIN
	INSERT INTO TB_ECM_POD(
		 POD_JOB_NO
		,ENT_CODE
		,OD_JOB_NO
		,POD_STATUS
		,POD_NAME
		,POD_DATE
		,POD_TIME
		,BL_NO
		,DELIVERY_CODE
		,REGISTER_USER_ID
		,REGISTER_DATE_TIME
		,UPDATE_USER_ID
		,UPDATE_DATE_TIME
	)VALUES(
		 #{podJobNo}
		,#{entCode}
		,#{OD_JOB_NO}
		,'ECM340'
		,'배송요청'
		,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
		,CONVERT(VARCHAR(5), DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE()), 108)
		,(SELECT HBL_NO FROM TB_ECM_OD WHERE ENT_CODE = #{entCode} AND DELIVERY_CODE = #{DELIVERY_CODE} AND OD_JOB_NO = #{OD_JOB_NO})
		,#{DELIVERY_CODE}
		,#{registerUserId}
		,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
		,#{registerUserId}
		,DATEADD(HOUR, cast(#{gmtTime} AS int), GETDATE())
	);			
	END

