/** OdMapper.countMulti */
SELECT count(*)
FROM TB_ECM_OD_MULTI
WHERE
	OD_JOB_NO = #{odJobNo}

/** OdMapper.countMultiByDelNo */
SELECT count(*)
FROM TB_ECM_OD_MULTI
WHERE
	DELIVERY_NO = #{deliveryNo}

/** OdMapper.countOdbyHbl */
SELECT count(*)
FROM TB_ECM_OD
WHERE
	HBL_NO = #{hblNo}

/* deliveryMapper.selectSendDeliveryListToOdSingle : Delivery 각 배송사에 해당하는 데이터 조회 */ SELECT mti.PAYMENT_GUBN AS DELIVERY_PAYMENT_TYPE_MULTI ,od.COMMODITY_ITEM AS commodityItemLocConvertMulti ,mti.DIM_WIDTH AS DIM_WIDTH_MULTI ,mti.DIM_LENGTH AS DIM_LENGTH_MULTI ,mti.DIM_HEIGHT AS DIM_HEIGHT_MULTI ,mti.VWT AS VWT_MULTI ,mti.DELIVERY_NO_CHANGED AS DELIVERY_NO_CHANGED ,od.DIM_WIDTH AS DIM_WIDTH ,od.DIM_LENGTH AS DIM_LENGTH ,od.DIM_HEIGHT AS DIM_HEIGHT ,od.VWT AS VWT ,(SELECT COUNT(*) FROM TB_ECM_OD_MULTI chkMul WHERE chkMul.OD_JOB_NO = od.OD_JOB_NO) AS MULTI_COUNT ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM360_POD_JOB_NO_MULTI ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' ) A ) AS ECM360_POD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM410' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM410_POD_JOB_NO_MULTI ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM410' ) A ) AS ECM410_POD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM340_POD_JOB_NO_MULTI ,(SELECT TOP 1 POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM504') AS ECM504_POD_JOB_NO ,(SELECT TOP 1 POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM504' AND BL_NO = mti.DELIVERY_NO) AS ECM504_POD_JOB_NO_MULTI , od.HBL_NO , od.OD_JOB_NO , od.HSN , od.CUST_CODE_LV1 AS AGENT_CODE , od.DEST_PORT , ad.LAST_POD_STATUS , od.VESSEL_FLIGHT , od.PO_NO AS CHK_PO_NO , CASE ISNULL(od.PO_NO,'') WHEN '' THEN od.HBL_NO ELSE od.PO_NO END PO_NO , od.CONSIGNEE_NAME_LOC , od.CONSIGNEE_NAME , od.CONSIGNEE_ZIPCODE , od.CONSIGNEE_ADDRESS , od.CONSIGNEE_ADDRESS_A , od.CONSIGNEE_ADDRESS_B , od.PIECES , od.CBM , od.GWT , od.DELIVERY_NOTE , od.AMOUNT_CUR , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '1'),'|','') as commodityItem1 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '2'),'|','') as commodityItem2 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '3'),'|','') as commodityItem3 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '4'),'|','') as commodityItem4 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '5'),'|','') as commodityItem5 , od.COMMODITY_ITEM AS commodityItemLocConvert , od.PIECES_REAL , od.SHIPPER_NAME AS shipperNameConvert , COALESCE(NULLIF(mti.CONSIGNEE_NAME_LOC_M, ''), (CASE WHEN ISNULL(od.CONSIGNEE_NAME_LOC,'') = '' THEN ISNULL(od.CONSIGNEE_NAME,'') ELSE ISNULL(od.CONSIGNEE_NAME_LOC,'') END)) AS consigneeNameLocConvert , od.SHIPPER_ZIPCODE AS shipperZipcodeConvert , od.SHIPPER_ADDRESS + ISNULL(od.SHIPPER_ADDRESS_A,'') + ISNULL(od.SHIPPER_ADDRESS_B,'') + ISNULL(od.SHIPPER_ADDRESS_C,'') + ISNULL(od.SHIPPER_ADDRESS_D,'') AS shipperAddressLocConvert , od.SHIPPER_TEL AS shipperTelConvert , od.SHIPPER_HP AS shipperMobileConvert ,COALESCE(NULLIF(mti.CONSIGNEE_ZIPCODE_M, ''), od.CONSIGNEE_ZIPCODE) AS consigneeZipcodeLocConvert ,COALESCE(NULLIF(mti.CONSIGNEE_ADDRESS_LOC_M, ''), (LEFT(REPLACE(ISNULL(od.CONSIGNEE_ADDRESS_LOC, od.CONSIGNEE_ADDRESS + ISNULL(od.CONSIGNEE_ADDRESS_A, '') + ISNULL(od.CONSIGNEE_ADDRESS_B, '') + ISNULL(od.CONSIGNEE_ADDRESS_C, '') + ISNULL(od.CONSIGNEE_ADDRESS_D, '')), '|', ' '),200))) AS consigneeAddressLocConvert , od.TR_CODE , od.DELIVERY_CODE , od.MBL_NO , od.DELIVERY_PAYMENT_TYPE , od.BOUND , od.BOUND_TYPE , mti.DELIVERY_CODE AS DELIVERY_CODE_MULTI , #{registerUserId} AS registerUserId , #{registerUserName} AS registerUserName , GETDATE() AS gmtTime ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' ) A ) AS ECM340_POD_JOB_NO , mti.DELIVERY_NO , mti.SEQ_NO_ID
, CASE WHEN ISNULL(od.CONSIGNEE_HP_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) END AS CONSIGNEE_HP , COALESCE(NULLIF(mti.CONSIGNEE_TEL_M, ''), (dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1))) AS consigneeHpConvert , dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS consigneeTelConvert
, CASE WHEN ISNULL(od.CONSIGNEE_HP,'') = '' THEN ISNULL(od.CONSIGNEE_TEL,'') ELSE ISNULL(od.CONSIGNEE_HP,'') END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL,'') = '' THEN ISNULL(od.CONSIGNEE_HP,'') ELSE ISNULL(od.CONSIGNEE_TEL,'') END AS CONSIGNEE_HP , COALESCE(NULLIF(mti.CONSIGNEE_TEL_M, ''), od.CONSIGNEE_HP) AS consigneeHpConvert , od.CONSIGNEE_TEL AS consigneeTelConvert
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI mti ON od.OD_JOB_NO = mti.OD_JOB_NO WHERE ( ISNULL(od.HBL_NO,'') != '' OR od.DELIVERY_CODE = 'KD' )
AND od.DELIVERY_CODE = #{deliveryCode}
AND od.HBL_NO = #{deliveryNoChanged} AND mti.SEQ_NO_ID = #{seq} ORDER BY od.CUST_CODE_LV1

/* deliveryMapper.selectSendDeliveryListToMultiSingle : Delivery 각 배송사에 해당하는 데이터 조회 */ SELECT mti.PAYMENT_GUBN AS DELIVERY_PAYMENT_TYPE_MULTI ,od.COMMODITY_ITEM AS commodityItemLocConvertMulti ,mti.DIM_WIDTH AS DIM_WIDTH_MULTI ,mti.DIM_LENGTH AS DIM_LENGTH_MULTI ,mti.DIM_HEIGHT AS DIM_HEIGHT_MULTI ,mti.VWT AS VWT_MULTI ,od.DIM_WIDTH AS DIM_WIDTH ,od.DIM_LENGTH AS DIM_LENGTH ,od.DIM_HEIGHT AS DIM_HEIGHT ,od.VWT AS VWT ,mti.DELIVERY_NO_CHANGED AS DELIVERY_NO_CHANGED ,(SELECT COUNT(*) FROM TB_ECM_OD_MULTI chkMul WHERE chkMul.OD_JOB_NO = od.OD_JOB_NO) AS MULTI_COUNT ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM360_POD_JOB_NO_MULTI ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM360' ) A ) AS ECM360_POD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM410' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM410_POD_JOB_NO_MULTI ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM410' ) A ) AS ECM410_POD_JOB_NO ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' AND BL_NO = mti.DELIVERY_NO ) A ) AS ECM340_POD_JOB_NO_MULTI ,(SELECT TOP 1 POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM504') AS ECM504_POD_JOB_NO ,(SELECT TOP 1 POD_JOB_NO FROM TB_ECM_POD_04_M WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM504' AND BL_NO = mti.DELIVERY_NO) AS ECM504_POD_JOB_NO_MULTI , od.HBL_NO , od.OD_JOB_NO , od.HSN , od.CUST_CODE_LV1 AS AGENT_CODE , od.DEST_PORT , ad.LAST_POD_STATUS , od.VESSEL_FLIGHT , od.PO_NO AS CHK_PO_NO , CASE ISNULL(od.PO_NO,'') WHEN '' THEN od.HBL_NO ELSE od.PO_NO END PO_NO , od.CONSIGNEE_NAME_LOC , od.CONSIGNEE_NAME , od.CONSIGNEE_ZIPCODE , od.CONSIGNEE_ADDRESS , od.CONSIGNEE_ADDRESS_A , od.CONSIGNEE_ADDRESS_B , od.PIECES , od.CBM , od.GWT , od.DELIVERY_NOTE , od.AMOUNT_CUR , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '1'),'|','') as commodityItem1 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '2'),'|','') as commodityItem2 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '3'),'|','') as commodityItem3 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '4'),'|','') as commodityItem4 , REPLACE((SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM WHERE OD_JOB_NO = od.OD_JOB_NO and SEQ_NO_ID = '5'),'|','') as commodityItem5 , od.COMMODITY_ITEM AS commodityItemLocConvert , od.PIECES_REAL , od.SHIPPER_NAME AS shipperNameConvert , COALESCE(NULLIF(mti.CONSIGNEE_NAME_LOC_M, ''), (CASE WHEN ISNULL(od.CONSIGNEE_NAME_LOC,'') = '' THEN ISNULL(od.CONSIGNEE_NAME,'') ELSE ISNULL(od.CONSIGNEE_NAME_LOC,'') END)) AS consigneeNameLocConvert , od.SHIPPER_ZIPCODE AS shipperZipcodeConvert , od.SHIPPER_ADDRESS + ISNULL(od.SHIPPER_ADDRESS_A,'') + ISNULL(od.SHIPPER_ADDRESS_B,'') + ISNULL(od.SHIPPER_ADDRESS_C,'') + ISNULL(od.SHIPPER_ADDRESS_D,'') AS shipperAddressLocConvert , od.SHIPPER_TEL AS shipperTelConvert , od.SHIPPER_HP AS shipperMobileConvert ,COALESCE(NULLIF(mti.CONSIGNEE_ZIPCODE_M, ''), od.CONSIGNEE_ZIPCODE) AS consigneeZipcodeLocConvert , COALESCE(NULLIF(mti.CONSIGNEE_ADDRESS_LOC_M, ''), (LEFT(REPLACE(ISNULL(od.CONSIGNEE_ADDRESS_LOC, od.CONSIGNEE_ADDRESS + ISNULL(od.CONSIGNEE_ADDRESS_A, '') + ISNULL(od.CONSIGNEE_ADDRESS_B, '') + ISNULL(od.CONSIGNEE_ADDRESS_C, '') + ISNULL(od.CONSIGNEE_ADDRESS_D, '')), '|', ' '),200))) AS consigneeAddressLocConvert , od.TR_CODE , od.DELIVERY_CODE , od.MBL_NO , od.DELIVERY_PAYMENT_TYPE , od.BOUND , od.BOUND_TYPE , mti.DELIVERY_CODE AS DELIVERY_CODE_MULTI , #{registerUserId} AS registerUserId , #{registerUserName} AS registerUserName , GETDATE() AS gmtTime ,( SELECT TOP 1 A.POD_JOB_NO FROM( SELECT POD_JOB_NO FROM TB_ECM_POD WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' UNION ALL SELECT POD_JOB_NO FROM TB_ECM_POD_04 WHERE OD_JOB_NO = od.OD_JOB_NO AND POD_STATUS = 'ECM340' ) A ) AS ECM340_POD_JOB_NO , mti.DELIVERY_NO , mti.SEQ_NO_ID
, CASE WHEN ISNULL(od.CONSIGNEE_HP_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL_ENC,'') = '' THEN dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1) ELSE dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) END AS CONSIGNEE_HP , COALESCE(NULLIF(mti.CONSIGNEE_TEL_M, ''), (dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_HP_ENC, 1))) AS consigneeHpConvert , dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS consigneeTelConvert
, CASE WHEN ISNULL(od.CONSIGNEE_HP,'') = '' THEN ISNULL(od.CONSIGNEE_TEL,'') ELSE ISNULL(od.CONSIGNEE_HP,'') END AS CONSIGNEE_TEL , CASE WHEN ISNULL(od.CONSIGNEE_TEL,'') = '' THEN ISNULL(od.CONSIGNEE_HP,'') ELSE ISNULL(od.CONSIGNEE_TEL,'') END AS CONSIGNEE_HP , COALESCE(NULLIF(mti.CONSIGNEE_TEL_M, ''), od.CONSIGNEE_HP) AS consigneeHpConvert , od.CONSIGNEE_TEL AS consigneeTelConvert
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI mti ON od.OD_JOB_NO = mti.OD_JOB_NO WHERE ( ISNULL(od.HBL_NO,'') != '' OR od.DELIVERY_CODE = 'KD' )
AND od.DELIVERY_CODE = #{deliveryCode}
AND mti.DELIVERY_NO = #{deliveryNoChanged} ORDER BY od.CUST_CODE_LV1

/* deliveryMapper.beforeOdChk : 잡넘버로 기본적인 데이터 조회 */
SELECT BOUND,BOUND_TYPE,CUSTOMS_CODE FROM TB_ECM_OD
WHERE OD_JOB_NO = 	#{odJobNo}

/** OdMapper.countRecOd */
SELECT count(*)
FROM TB_ECM_POD_04
WHERE
	BL_NO = #{hblNo}
  AND POD_STATUS = 'ECM360'

/** OdMapper.countRecMulti */
SELECT count(*)
FROM TB_ECM_POD_04_M
WHERE
	BL_NO = #{deliveryNo}
  AND POD_STATUS = 'ECM360'

/* deliveryMapper.selectDeliveryMListVE : Delivery-M List(main) 조회 */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT A.* , COUNT(A.MBL_NO) OVER() AS SUM_COUNT , SUM(A.HBL_CNT) OVER() AS SUM_HBLNO , SUM(A.HBL_PIECES) OVER() AS SUM_PIECES , SUM(A.HBL_GWT) OVER() AS SUM_GWT FROM( SELECT MAX(ISNULL(AR_DATE, '')) AS AR_DATE , MAX(ISNULL(OB_DATE, '')) AS OB_DATE , MAX(ISNULL(VESSEL_FLIGHT, '')) AS VESSEL_FLIGHT , MAX(ISNULL(ORIG_CODE, '')) AS ORIG_CODE , MAX(ISNULL(DEST_CODE, '')) AS DEST_CODE , MAX(ISNULL(MBL_NO, '')) AS MBL_NO , MAX(ISNULL(OD_JOB_NO, '')) AS OD_JOB_NO , MAX(ISNULL(MASTER_OD_JOB_NO, '')) AS MASTER_OD_JOB_NO , MAX(ISNULL(BOUND, '')) AS BOUND ,COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM340' THEN 1 END) + COUNT(DELIVERY_REQ) AS DELIVERY_REQ_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM360' THEN 1 END) + COUNT(DELIVERY_RECV) AS DELIVERY_RECV_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM400' THEN 1 END) + COUNT(UNDELIVERY) AS UNDELIVERY_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM410' THEN 1 END) + COUNT(DELIVERY_REQ_ERR) AS DELIVERY_REQ_ERR_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM420' THEN 1 END) + COUNT(DELIVERY) AS DELIVERY_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM361' THEN 1 END) + COUNT(DELIVERY_PICKUP) AS DELIVERY_PICKUP_CNT , COUNT(CASE ISNULL(DELIVERY_STATUS, '') WHEN 'ECM390' THEN 1 END) + COUNT(DELIVERY_START) AS DELIVERY_START_CNT , COUNT(CASE WHEN ISNULL(DELIVERY_CODE, '') = '' THEN 1 END) AS DELIVERY_UNSPECIFY_CNT , COUNT(CASE WHEN ISNULL(DELIVERY_CODE, '') != '' THEN 1 END) AS DELIVERY_DESIGNATE_CNT , COUNT(CASE WHEN ISNULL(DELIVERY_CODE, '') != '' AND ISNULL(DELIVERY_STATUS, '') < 'ECM340' THEN 1 END) AS DELIVERY_WAITING_CNT ,COUNT(DELIVERY_REQ) AS MUL_DELIVERY_REQ_CNT ,COUNT(DELIVERY_RECV) AS MUL_DELIVERY_RECV_CNT ,COUNT(UNDELIVERY) AS MUL_UNDELIVERY_CNT ,COUNT(DELIVERY_REQ_ERR) AS MUL_DELIVERY_REQ_ERR_CNT ,COUNT(DELIVERY) AS MUL_DELIVERY_CNT ,COUNT(DELIVERY_PICKUP) AS MUL_DELIVERY_PICKUP_CNT ,COUNT(DELIVERY_START) AS MUL_DELIVERY_START_CNT , SUM(PIECES) AS HBL_PIECES , SUM(GWT) AS HBL_GWT , COUNT(ISNULL(HBL_NO, 0)) AS HBL_CNT , COUNT(ISNULL(HBL_NO, 0)) AS TOTAL_HBL_CNT FROM ( SELECT od2.OD_JOB_NO ,od2.MBL_NO ,od2.DEST_CODE ,od2.ORIG_CODE ,od2.VESSEL_FLIGHT ,od2.AR_DATE ,od2.OB_DATE ,od2.MASTER_OD_JOB_NO ,od2.BOUND ,od2.PIECES ,od2.GWT ,od.HBL_NO ,CASE WHEN ISNULL(multi.OD_JOB_NO,'') = '' THEN ad.DELIVERY_STATUS ELSE '' END AS DELIVERY_STATUS ,od.DELIVERY_CODE ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM340') AS DELIVERY_REQ ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM360') AS DELIVERY_RECV ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM400') AS UNDELIVERY ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM410') AS DELIVERY_REQ_ERR ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM420') AS DELIVERY ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM361') AS DELIVERY_PICKUP ,(SELECT MAX(POD_STATUS) FROM TB_ECM_POD_04_M pod4 WHERE OD_JOB_NO = multi.OD_JOB_NO AND POD_STATUS = 'ECM390') AS DELIVERY_START FROM TB_ECM_OD od2 INNER JOIN TB_ECM_OD od ON od.MASTER_OD_JOB_NO = od2.OD_JOB_NO AND od.BL_TYPE_MH = 'H' INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_MULTI multi ON multi.OD_JOB_NO = od.OD_JOB_NO WHERE od2.ENT_CODE = #{srchEntCode} AND od2.BL_TYPE_MH = 'M'
) AA GROUP BY OD_JOB_NO )A

mapper.update:
/* deliveryMapper.updateChangeDelivery : Delivery 배송사 지정 */
UPDATE TB_ECM_OD_MULTI
SET DELIVERY_CODE = #{deliveryCode}
  , UPDATE_USER_ID = #{registerUserId}
  , UPDATE_DATE_TIME = GETDATE()
WHERE SEQ_NO_ID = #{seqNoId}
  AND OD_JOB_NO = #{odJobNo}

		/* deliveryMapper.updateMulDate : 멀티변경송장번호 변경(송장교체)*/
		UPDATE TB_ECM_OD_MULTI
		SET
			DELIVERY_NO_CHANGED = #{stockMutliNo}
		WHERE OD_JOB_NO = #{odJobNo}
		AND SEQ_NO_ID = #{seqNoId}

		UPDATE TB_ECM_OD_DLV_CHANGE_INFO
		SET
			DELIVERY_NO_CHANGED = #{stockMutliNo}
		WHERE OD_JOB_NO = #{odJobNo}
		  AND SEQ_NO_ID = #{seqNoId}

mapper.delete:
/* InvoiceMapper.deleteChkPod : 변경송장 이전데이터 삭제 */
		DELETE FROM TB_ECM_POD_04_M
		WHERE OD_JOB_NO = #{odJobNo}
		AND BL_NO = #{checkDelNo}

mapper.select:
/* InvoiceMapper.selectCheckNo : 변경송장 이전데이터 삭제정보 */
SELECT TOP 1 DELIVERY_NO from TB_ECM_OD_MULTI
WHERE OD_JOB_NO = #{odJobNo}
  AND SEQ_NO_ID = #{seqNoId}

/* deliveryMapper.selectHoldSingleStatus : 보류 대상 단건 현재 배송상태 조회 */
SELECT ISNULL(DELIVERY_STATUS, '') FROM TB_ECM_OD_ADDITIONAL
WHERE OD_JOB_NO = #{odJobNo}

/* deliveryMapper.selectHoldMultiStatus : 보류 대상 멀티 현재 배송상태(POD_04_M MAX) 조회 */
SELECT ISNULL(MAX(POD_STATUS), '') FROM TB_ECM_POD_04_M
WHERE OD_JOB_NO = #{odJobNo}
  AND BL_NO = LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))

mapper.update:
		/* deliveryMapper.holdDeliverySingle : Delivery 보류(ECM425) - 단건 배송상태 업데이트 + POD(TB_ECM_POD_04) 저장 */
		UPDATE TB_ECM_OD_ADDITIONAL
		SET DELIVERY_STATUS = 'ECM425'
		WHERE OD_JOB_NO = #{odJobNo};

		INSERT INTO TB_ECM_POD_04(
			 POD_JOB_NO
			,ENT_CODE
			,OD_JOB_NO
			,BL_NO
			,DELIVERY_CODE
			,POD_STATUS
			,POD_DATE
			,POD_TIME
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
			,UPDATE_USER_ID
			,UPDATE_DATE_TIME
		)VALUES(
			 #{podJobNo}
			,#{entCode}
			,#{odJobNo}
			,LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))
			,#{deliveryCode}
			,'ECM425'
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)
			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
		);

		/* deliveryMapper.holdDeliveryMulti : Delivery 보류(ECM425) - 멀티 반품배송상태 업데이트(seqNo 기준) + POD(TB_ECM_POD_04_M) 저장 */
		UPDATE TB_ECM_OD_MULTI
		SET RETURN_DELIVERY_STATUS = 'ECM425'
		  , UPDATE_USER_ID = #{updateUserId}
		  , UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
		WHERE OD_JOB_NO = #{odJobNo}
		  AND SEQ_NO_ID = #{seqNoId};

		INSERT INTO TB_ECM_POD_04_M(
			 POD_JOB_NO
			,ENT_CODE
			,OD_JOB_NO
			,BL_NO
			,DELIVERY_CODE
			,POD_STATUS
			,POD_DATE
			,POD_TIME
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
			,UPDATE_USER_ID
			,UPDATE_DATE_TIME
		)VALUES(
			 #{podJobNo}
			,#{entCode}
			,#{odJobNo}
			,LTRIM(RTRIM(REPLACE(#{blNo},char(9),'')))
			,#{deliveryCode}
			,'ECM425'
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)
			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
			,#{updateUserId}
			,DATEADD(HOUR, ${gmtTime}, GETDATE())
		);
